// Returns:
// -1 if impossible
//  0 if possible with no refuels at the station
//  1 if possible and at least one refuel at the station is needed
fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    // Promote to i32 to avoid overflow in expressions like 2*a - f
    let a = a as i32;
    let b = b as i32;
    let f = f as i32;
    let k = k as i32;

    let start_to_station = f;
    let station_to_far = a - f;
    let two_a_minus_f = 2 * a - f;

    // Basic reachability: must be able to reach station from either end,
    // and must be able to go from station to the opposite endpoint.
    if b < start_to_station || b < station_to_far {
        return -1;
    }

    if k == 1 {
        // For one trip: feasible if we can either go straight (b>=a)
        // or reach station first (b>=f) and then refuel to finish.
        if b < a && b < f {
            return -1;
        }
        return if b >= a { 0 } else { 1 };
    }

    // For k > 1, per stated conditions we also require b >= (2*a - f)
    if b < two_a_minus_f {
        return -1;
    }

    // If b >= 2*a, then on any leg you can always do endpoint->endpoint
    // without refueling at the station, hence no station refuels ever needed.
    if b >= 2 * a {
        return 0;
    }

    // Otherwise, multiple journeys are feasible (given the checks),
    // but at least one station refuel is needed somewhere.
    1
}